    deleteNotebook(id: number): void
    getSourcesForNotebook(id: number): NotebookSource[]
    createSource(notebookId: number, partial: Omit<NotebookSource, 'id' | 'created_at'>): number
    updateSourceStatus(sourceId: number, status: NotebookSource['status'], errorMsg?: string): void
    deleteSource(sourceId: number): void
    saveChunks(sourceId: number, chunks: Pick<NotebookChunk, 'chunk_index' | 'content' | 'token_count' | 'metadata'>[]): void
    updateChunkEmbedding(chunkId: number, embedding: number[]): void
    getEmbeddedChunks(notebookId: number): NotebookChunk[]
    saveDoc(notebookId: number, doc: Omit<NotebookDoc, 'id' | 'created_at' | 'updated_at'>): number
    getDoc(docId: number): NotebookDoc | null
    listDocs(notebookId: number): NotebookDoc[]
    deleteDoc(docId: number): void
    saveMessage(notebookId: number, role: 'user' | 'assistant', content: string, sourcesUsed?: number[]): number
    getMessages(notebookId: number): { id: number; role: string; content: string; sources_used: string | null; created_at: string }[]
}
```

