    const r = await apiFetch(`/api/notebook/notebooks/${notebookId}/viz/topics`);
    return r.json();
}

export async function getSentiment(notebookId: number): Promise<any> {
    const r = await apiFetch(`/api/notebook/notebooks/${notebookId}/viz/sentiment`);
    return r.json();
}

