import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
    Notebook, NotebookSource, NotebookDoc, NotebookMessage, DocType,
    listNotebooks, createNotebook, deleteNotebook, getNotebook,
    listSources, loadMessages, listDocs,
    streamGenerate
} from '../../../lib/notebookBridge';
import { SourcesPanel } from './SourcesPanel';
import { ChatPane } from './ChatPane';
import { GeneratedDocsSection } from './GeneratedDocsSection';
import { VizPanel } from './VizPanel';

type RightTab = 'chat' | 'docs' | 'viz';

const DEFAULT_MODEL = 'qwen-liberated:latest';

export default function NotebookTab() {
    const [notebooks, setNotebooks] = useState<Notebook[]>([]);
    const [selectedId, setSelectedId] = useState<number | null>(null);
    const [sources, setSources] = useState<NotebookSource[]>([]);
    const [messages, setMessages] = useState<NotebookMessage[]>([]);
    const [docs, setDocs] = useState<NotebookDoc[]>([]);
    const [rightTab, setRightTab] = useState<RightTab>('chat');
    const [generating, setGenerating] = useState(false);
    const [generatePreview, setGeneratePreview] = useState('');
    const [loading, setLoading] = useState(true);
    const esRef = useRef<any>(null);

    // Initial load
    useEffect(() => {
        loadAll();
    }, []);

    async function loadAll() {
        setLoading(true);
        try {
            const nbs = await listNotebooks();
            setNotebooks(nbs);
            if (nbs.length > 0) {
                await selectNotebook(nbs[0].id, nbs);
            }
        } catch (e: any) {
            console.error('NotebookTab load error:', e.message);
        } finally {
            setLoading(false);
        }
    }

    async function selectNotebook(id: number, nbs?: Notebook[]) {
        setSelectedId(id);
        try {
            const [srcs, msgs, docList] = await Promise.all([
                apiFetch_sources(id),
                loadMessages(id),
                apiFetch_docs(id)
            ]);
            setSources(srcs);
            setMessages(msgs);
            setDocs(docList);
        } catch (e: any) {
            console.error('selectNotebook error:', e.message);
        }
    }

    async function apiFetch_sources(id: number): Promise<NotebookSource[]> {
        try { return await listSources(id); } catch { return []; }
    }

    async function apiFetch_docs(id: number): Promise<NotebookDoc[]> {
        try { return await listDocs(id); } catch { return []; }
    }

    async function handleCreateNotebook() {
        const title = `Notebook ${new Date().toLocaleDateString()}`;
        try {
            const nb = await createNotebook(title);
            const updated = [nb, ...notebooks];
            setNotebooks(updated);
            await selectNotebook(nb.id, updated);
        } catch (e: any) {
            console.error('Create notebook error:', e.message);
        }
    }

    async function handleDeleteNotebook(id: number) {
        if (!confirm('Delete this notebook and all its sources?')) return;
        try {
            await deleteNotebook(id);
            const updated = notebooks.filter(n => n.id !== id);
            setNotebooks(updated);
            if (updated.length > 0) {
                await selectNotebook(updated[0].id, updated);
            } else {
                setSelectedId(null);
                setSources([]);
                setMessages([]);
                setDocs([]);
            }
        } catch (e: any) {
            console.error('Delete notebook error:', e.message);
        }
    }

    async function refreshSources() {
        if (selectedId == null) return;
        const srcs = await apiFetch_sources(selectedId);
        setSources(srcs);
    }

    async function refreshDocs() {
        if (selectedId == null) return;
        const docList = await apiFetch_docs(selectedId);
        setDocs(docList);
    }

    function handleGenerate(docType: DocType) {
        if (!selectedId || generating) return;
        setGenerating(true);
        setGeneratePreview('');
        setRightTab('docs');

        let preview = '';
        esRef.current?.close?.();
        esRef.current = streamGenerate(selectedId, docType, DEFAULT_MODEL, {
            onToken: (token) => {
                preview += token;
                setGeneratePreview(preview.slice(-120));
            },
            onDone: async (docId) => {
                setGenerating(false);
                setGeneratePreview('');
                await refreshDocs();
            },
            onError: (msg) => {
                setGenerating(false);
                setGeneratePreview('');
                console.error('Generate error:', msg);
            }
        });
    }

    const RIGHT_TABS: { id: RightTab; label: string }[] = [
        { id: 'chat', label: 'Chat' },
        { id: 'docs', label: `Docs${docs.length ? ` (${docs.length})` : ''}` },
        { id: 'viz', label: 'Visualize' }
    ];

    if (loading) {
        return (
            <div className="nb-root nb-loading">
                ⬡ Loading notebooks…
                <style>{NB_STYLES}</style>
            </div>
        );
    }

    return (
        <div className="nb-root">
            {/* Left: Sources Panel */}
            <div className="nb-left">
                <SourcesPanel
                    notebooks={notebooks}
                    selectedId={selectedId}
                    sources={sources}
                    onSelectNotebook={id => selectNotebook(id)}
                    onCreateNotebook={handleCreateNotebook}
                    onDeleteNotebook={handleDeleteNotebook}
                    onSourcesChanged={refreshSources}
                />
            </div>

            {/* Right: Chat / Docs / Viz */}
            <div className="nb-right">
                <div className="nb-right-tabs">
                    {RIGHT_TABS.map(t => (
                        <button
                            key={t.id}
                            className={`nb-right-tab ${rightTab === t.id ? 'active' : ''}`}
                            onClick={() => setRightTab(t.id)}
                        >
                            {t.label}
                        </button>
                    ))}
                </div>

                <div className="nb-right-content">
                    {selectedId == null ? (
                        <div className="nb-empty-state">
                            <div className="nb-empty-icon">◧</div>
                            <div>Create a notebook to get started</div>
                            <button className="nb-btn" onClick={handleCreateNotebook}>
                                + New Notebook
                            </button>
                        </div>
                    ) : (
                        <>
                            {rightTab === 'chat' && (
                                <ChatPane
                                    notebookId={selectedId}
                                    initialMessages={messages}
                                    model={DEFAULT_MODEL}
                                />
                            )}
                            {rightTab === 'docs' && (
                                <GeneratedDocsSection
                                    docs={docs}
                                    generating={generating}
                                    generatePreview={generatePreview}
                                    onGenerate={handleGenerate}
                                    onDocsChanged={refreshDocs}
                                />
                            )}
                            {rightTab === 'viz' && (
                                <VizPanel notebookId={selectedId} />
                            )}
                        </>
                    )}
                </div>
            </div>

            <style>{NB_STYLES}</style>
        </div>
    );
}

