40	export class NotebookVizService {
41	    private notebookService: NotebookService;
42	    private cache = new Map<string, CacheEntry<unknown>>();
43	    private TTL = 5 * 60 * 1000;
44	
45	    constructor(notebookService: NotebookService) {
46	        this.notebookService = notebookService;
47	    }
48	
49	    async getEntityFrequencies(notebookId: number): Promise<EntityFreqData[]> {
50	        return this.cached(`entities:${notebookId}`, async () => {
51	            const text = this.getSourceText(notebookId);
52	            const prompt = `Analyze the following text and extract named entities. Return ONLY valid JSON array in this exact format:
53	[{"entity": "Name", "count": N, "type": "person|org|place|concept"}]
54	Extract 10-20 most prominent entities. Sort by count descending.
55	
56	Text:
57	${text.slice(0, 8000)}`;
58	            return await this.extractJson<EntityFreqData[]>(prompt, 'entity-freq') || [];
59	        });
60	    }
61	
62	    async getTemporalSeries(notebookId: number): Promise<TemporalPoint[]> {
63	        return this.cached(`temporal:${notebookId}`, async () => {
64	            const text = this.getSourceText(notebookId);
65	            const prompt = `Analyze the following text and extract all temporal events, dates, and time references. Return ONLY valid JSON array:
66	[{"date": "YYYY-MM-DD or descriptive period", "eventTitle": "Brief event description", "count": 1}]
67	Extract up to 15 events. Sort chronologically.
68	
69	Text:
70	${text.slice(0, 8000)}`;
71	            return await this.extractJson<TemporalPoint[]>(prompt, 'temporal') || [];
72	        });
73	    }
74	
75	    async getTopicGraph(notebookId: number): Promise<{ nodes: TopicNode[]; edges: TopicEdge[] }> {
76	        return this.cached(`topics:${notebookId}`, async () => {
77	            const text = this.getSourceText(notebookId);
78	            const prompt = `Analyze the following text and identify topic clusters and their relationships. Return ONLY valid JSON object:
79	{"nodes": [{"id": "topic-id", "label": "Topic Name", "weight": 0.0-1.0}], "edges": [{"source": "id1", "target": "id2", "weight": 0.0-1.0}]}
80	Include 8-12 nodes and meaningful edges showing topic co-occurrence.
81	
82	Text:
83	${text.slice(0, 8000)}`;
84	            return await this.extractJson<{ nodes: TopicNode[]; edges: TopicEdge[] }>(prompt, 'topics') || { nodes: [], edges: [] };
85	        });
86	    }
87	
88	    async getSentiment(notebookId: number): Promise<SentimentResult> {
89	        return this.cached(`sentiment:${notebookId}`, async () => {
90	            const text = this.getSourceText(notebookId);
91	            const prompt = `Perform sentiment analysis on the following text. Return ONLY valid JSON:
92	{"positive": 0.0-1.0, "neutral": 0.0-1.0, "negative": 0.0-1.0, "compound": -1.0 to 1.0}
93	Ensure positive + neutral + negative = 1.0. compound is -1 (most negative) to +1 (most positive).
94	
95	Text:
96	${text.slice(0, 8000)}`;
97	            return await this.extractJson<SentimentResult>(prompt, 'sentiment') || { positive: 0.33, neutral: 0.34, negative: 0.33, compound: 0 };
98	        });
99	    }
100	
101	    private getSourceText(notebookId: number): string {
102	        const chunks = this.notebookService.getEmbeddedChunks(notebookId);
103	        if (chunks.length === 0) {
104	            // Fall back to all chunks (not yet embedded)
105	            const sources = this.notebookService.listSources(notebookId);
106	            return sources.map(s => s.title).join('. ');
107	        }
108	        return chunks.map(c => c.content).join('\n\n');
109	    }
110	
111	    private async extractJson<T>(prompt: string, label: string): Promise<T | null> {
112	        try {
113	            const response = await neuralForge.chat(
114	                'qwen-liberated:latest',
115	                [{ role: 'user', content: prompt }],
116	                'You are a JSON extraction assistant. Return only valid JSON, no markdown code blocks, no explanations.'
117	            );
118	
119	            const raw = response.content?.trim() || '';
120	            // Strip markdown code blocks if model disobeys
121	            const cleaned = raw.replace(/^```json?\n?/, '').replace(/\n?```$/, '').trim();
122	            return JSON.parse(cleaned) as T;
123	        } catch (e: any) {
124	            console.error(`⬡ NOTEBOOK_VIZ_ERROR :: ${label} :: ${e.message}`);
125	            return null;
126	        }
127	    }
128	
129	    private async cached<T>(key: string, fn: () => Promise<T>): Promise<T> {
130	        const existing = this.cache.get(key) as CacheEntry<T> | undefined;
131	        if (existing && existing.expires > Date.now()) return existing.data;
132	
133	        const data = await fn();
134	        this.cache.set(key, { data, expires: Date.now() + this.TTL });
135	        return data;
136	    }
137	
138	    invalidateCache(notebookId: number): void {
139	        for (const key of this.cache.keys()) {
140	            if (key.includes(`:${notebookId}`)) this.cache.delete(key);
141	        }
142	    }
143	}

