// ── Types ──────────────────────────────────────────────────────────────────────

interface Notebook {
    id: number;
    title: string;
    description: string | null;
    model_id: string;
    created_at: string;
}

interface Source {
    id: number;
    notebook_id: number;
    title: string;
    source_type: string;
    status: 'pending' | 'processing' | 'ready' | 'error';
    error_msg: string | null;
    word_count: number;
    created_at: string;
}

interface Doc {
    id: number;
    notebook_id: number;
    doc_type: string;
    title: string;
    content: string;
    pdf_path: string | null;
    obsidian_path: string | null;
    created_at: string;
}

interface Message {
    id: number;
    role: 'user' | 'assistant';
    content: string;
    created_at: string;
}

interface EntityFreq { entity: string; count: number; type: string; }
