11	export function NetworkGraph({ nodes, edges }: { nodes: TopicNode[]; edges: TopicEdge[] }) {
12	    const canvasRef = useRef<HTMLCanvasElement>(null);
13	    const rafRef = useRef<number>(0);
14	
15	    useEffect(() => {
16	        const canvas = canvasRef.current;
17	        if (!canvas || !nodes.length) return;
18	        const ctx = canvas.getContext('2d') as CanvasRenderingContext2D;
19	        if (!ctx) return;
20	
21	        const dpr = window.devicePixelRatio || 1;
22	        const w = canvas.clientWidth;
23	        const h = canvas.clientHeight;
24	        canvas.width = w * dpr;
25	        canvas.height = h * dpr;
26	        ctx.scale(dpr, dpr);
27	
28	        // Initialize positions randomly
29	        const sims: NodeSim[] = nodes.map(n => ({
30	            ...n,
31	            x: w * 0.1 + Math.random() * w * 0.8,
32	            y: h * 0.1 + Math.random() * h * 0.8,
33	            vx: 0, vy: 0
34	        }));
35	
36	        const idMap = new Map(sims.map(n => [n.id, n]));
37	        let frame = 0;
38	
39	        function tick() {
40	            // Repulsion between nodes
41	            for (let i = 0; i < sims.length; i++) {
42	                for (let j = i + 1; j < sims.length; j++) {
43	                    const dx = sims[j].x - sims[i].x;
44	                    const dy = sims[j].y - sims[i].y;
45	                    const dist = Math.sqrt(dx * dx + dy * dy) || 1;
46	                    const force = 2000 / (dist * dist);
47	                    sims[i].vx -= (dx / dist) * force;
48	                    sims[i].vy -= (dy / dist) * force;
49	                    sims[j].vx += (dx / dist) * force;
50	                    sims[j].vy += (dy / dist) * force;
51	                }
52	            }
53	
54	            // Attraction along edges
55	            for (const edge of edges) {
56	                const src = idMap.get(edge.source);
57	                const tgt = idMap.get(edge.target);
58	                if (!src || !tgt) continue;
59	                const dx = tgt.x - src.x;
60	                const dy = tgt.y - src.y;
61	                const dist = Math.sqrt(dx * dx + dy * dy) || 1;
62	                const target = 120;
63	                const force = (dist - target) * 0.02 * (edge.weight || 0.5);
64	                src.vx += (dx / dist) * force;
65	                src.vy += (dy / dist) * force;
66	                tgt.vx -= (dx / dist) * force;
67	                tgt.vy -= (dy / dist) * force;
68	            }
69	
70	            // Center gravity
71	            const cx = w / 2, cy = h / 2;
72	            for (const n of sims) {
73	                n.vx += (cx - n.x) * 0.003;
74	                n.vy += (cy - n.y) * 0.003;
75	                n.vx *= 0.85;
76	                n.vy *= 0.85;
77	                n.x += n.vx;
78	                n.y += n.vy;
79	                n.x = Math.max(30, Math.min(w - 30, n.x));
80	                n.y = Math.max(20, Math.min(h - 20, n.y));
81	            }
82	        }
83	
84	        function draw() {
85	            ctx.clearRect(0, 0, w, h);
86	
87	            // Edges
88	            for (const edge of edges) {
89	                const src = idMap.get(edge.source);
90	                const tgt = idMap.get(edge.target);
91	                if (!src || !tgt) continue;
92	                ctx.beginPath();
93	                ctx.moveTo(src.x, src.y);
94	                ctx.lineTo(tgt.x, tgt.y);
95	                ctx.strokeStyle = `rgba(0,229,255,${(edge.weight || 0.5) * 0.4})`;
96	                ctx.lineWidth = 1;
97	                ctx.stroke();
98	            }
99	
100	            // Nodes
101	            for (const n of sims) {
102	                const r = 6 + (n.weight || 0.5) * 12;
103	                ctx.beginPath();
104	                ctx.arc(n.x, n.y, r, 0, Math.PI * 2);
105	                ctx.fillStyle = 'rgba(0,229,255,0.15)';
106	                ctx.fill();
107	                ctx.strokeStyle = '#00e5ff';
108	                ctx.lineWidth = 1.5;
109	                ctx.stroke();
110	
111	                ctx.fillStyle = '#e8e8f0';
112	                ctx.font = '10px JetBrains Mono, monospace';
113	                ctx.textAlign = 'center';
114	                ctx.fillText(n.label.slice(0, 16), n.x, n.y + r + 12);
115	            }
116	        }
117	
118	        function loop() {
119	            if (frame < 200) tick();
120	            draw();
121	            frame++;
122	            if (frame < 400) rafRef.current = requestAnimationFrame(loop);
123	        }
124	
125	        rafRef.current = requestAnimationFrame(loop);
126	        return () => cancelAnimationFrame(rafRef.current);
127	    }, [nodes, edges]);
128	
129	    return (
130	        <canvas
131	            ref={canvasRef}
132	            style={{ width: '100%', height: '100%', display: 'block' }}
133	        />
134	    );
135	}

