10	export function SentimentGauge({ data }: { data: SentimentResult }) {
11	    const { positive, neutral, negative, compound } = data;
12	    const r = 80;
13	    const cx = 120;
14	    const cy = 110;
15	    const sweep = Math.PI;
16	
17	    function arc(start: number, end: number) {
18	        const s = start * sweep;
19	        const e = end * sweep;
20	        const x1 = cx + r * Math.cos(Math.PI + s);
21	        const y1 = cy + r * Math.sin(Math.PI + s);
22	        const x2 = cx + r * Math.cos(Math.PI + e);
23	        const y2 = cy + r * Math.sin(Math.PI + e);
24	        const large = (e - s) > Math.PI ? 1 : 0;
25	        return `M ${x1} ${y1} A ${r} ${r} 0 ${large} 1 ${x2} ${y2}`;

